package uz.mirix.tracelens.internal;
import uz.mirix.tracelens.*; import java.util.*; import java.util.concurrent.atomic.AtomicInteger;
public final class ServerTimingFormatter {private ServerTimingFormatter(){} public static String format(TraceReport report,TraceLensProperties p){int limit=Math.min(p.getServerTiming().getMaxMetrics(),report.spans().size()+1);List<String> metrics=new ArrayList<>(limit);AtomicInteger seq=new AtomicInteger();for(TraceSpan span:report.spans()){if(metrics.size()>=limit-1)break;String token=span.category().name().toLowerCase(Locale.ROOT)+"-"+seq.incrementAndGet();String desc=SafeText.singleLine(span.name().replace("\\","\\\\").replace("\"","\\\""),p.getServerTiming().getMaxDescriptionLength());metrics.add(token+";dur="+millis(span.durationNanos())+";desc=\""+desc+"\"");}metrics.add("total;dur="+millis(report.durationNanos())+";desc=\"TraceLens total\"");return String.join(", ",metrics);} private static String millis(long nanos){return String.format(Locale.ROOT,"%.2f",nanos/1_000_000.0d);}}
